  const corrected = render(raw).replace("ERC20 history was scanned from block 0 through the pin across every selected strict family. Family commitments must agree before a row is accepted.", `ERC20 history covers the exact deployment window and a ${LOG_TAIL_BLOCKS}-block retained tail across every selected strict family. The middle range is explicitly gapped because providers reject wide log ranges; no global-history or full system-balance conservation claim is made. Family commitments must agree before a row is accepted.`);
  write(REPORT, corrected);
  const manifest = JSON.parse(fs.readFileSync(abs(MANIFEST), "utf8"));
  const records = RECORDS.map(hashFile), aggregateSha256 = sha(Buffer.from(records.map((x) => `${x.path}\0${x.bytes}\0${x.sha256}`).join("\n")));
  manifest.records = records; manifest.aggregateSha256 = aggregateSha256; write(MANIFEST, manifest);
  process.stdout.write(`${JSON.stringify({ status: "PASS", offline: true, runId: raw.runId, aggregateSha256 })}\n`);
