function applyCoverageCorrections() {
  const raw = JSON.parse(fs.readFileSync(abs(RAW), "utf8"));
  for (const asset of raw.assets) asset.callableSelectors = asset.callableSelectors.filter((row) => row.signature);
  const genesisSupplyConservationPass = raw.assets.every((asset) => asset.conservation.genesisMintEqualsCurrentTotalSupply === true);
  const nonUnanimousHistoryAssets = raw.assets.filter((asset) => asset.history.crossFamilyAgreement.unanimous !== true).length;
  raw.duplicateAndConservation = {
    duplicateCandidates: raw.duplicateAndConservation.duplicateCandidates,
    exactDuplicateEventRows: raw.duplicateAndConservation.exactDuplicateEventRows,
    retainedWindowHistoryThresholdPass: raw.duplicateAndConservation.historyAgreementPass,
    retainedWindowHistoryThreshold: "2-of-3 strict families",
    nonUnanimousHistoryAssets,
    genesisSupplyConservationPass,
    fullSystemBalanceConservation: "unknown-middle-history-gap",
    conclusion: "No duplicate key observed in the exact deployment windows, 10,000-block retained tails, or bounded API sample. Four asset histories met 2-of-3 but were not unanimous; this is not a global exactly-once or full conservation proof."
  };
  write(RAW, raw);
  const scopeSentence = `ERC20 deployment windows and ${LOG_TAIL_BLOCKS}-block tails were queried across three strict families and accepted only at an exact 2-of-3 threshold. ${nonUnanimousHistoryAssets}/5 asset histories were not unanimous. The middle range is explicitly gapped; no global-history or full system-balance conservation claim is made.`;
  write(REPORT, render(raw).replace("ERC20 history was scanned from block 0 through the pin across every selected strict family. Family commitments must agree before a row is accepted.", scopeSentence));
  const inbox = JSON.parse(fs.readFileSync(abs(INBOX), "utf8"));
  inbox.summary = "Fixed-pin state and genesis-mint/current-supply conservation passed; retained history is 2-of-3 with a middle gap, and exactly-once remains MODEL_ONLY with no deployed duplicate primitive.";
  write(INBOX, inbox);
  const handoff = `# Unit / Hyperunit exactly-once decimal Step 1 handoff\n\n- Run \`${raw.runId}\`; ${raw.classification}; pipeline 0/5; gates 0/0/false; fork=false.\n- Pin ${raw.pin.blockNumber} / \`${raw.pin.blockHash}\`; strict families 3; terminal recheck PASS; backend independence unproven.\n- Strict assets ${raw.scope.strictAssets.join(", ")}; UXPL separately caveated.\n- Fixed-pin state threshold PASS. Retained deployment/tail history threshold PASS at 2-of-3; nonunanimous assets=${nonUnanimousHistoryAssets}/5; middle history gapped.\n- Genesis mint equals current total supply=${genesisSupplyConservationPass}; full system-balance conservation=unknown; duplicate candidates=0.\n- API operation rows=${raw.operationApi.operationRowsObserved}; address generation/retry/submit not called. GraphQL is prefilter only.\n- Tests ${raw.tests.deterministicAssertions} deterministic, ${raw.tests.fuzzIterations} iterations/${raw.tests.fuzzEffectiveCases} effective fuzz PASS; exactly-once MODEL_ONLY.\n- Next gate: ${raw.nextGate}\n`;
  write(HANDOFF, handoff);
  const leak = leakScan([JSON.stringify(raw), JSON.stringify(raw.tests), fs.readFileSync(abs(REPORT), "utf8"), JSON.stringify(inbox), handoff], new Set()); write(LEAK, leak); if (leak.status !== "PASS") throw new Error("offline-leak-scan-failed");
  const manifest = JSON.parse(fs.readFileSync(abs(MANIFEST), "utf8")); manifest.duplicateAndConservation = raw.duplicateAndConservation; manifest.leakScan = leak; const records = RECORDS.map(hashFile); manifest.records = records; manifest.aggregateSha256 = sha(Buffer.from(records.map((x) => `${x.path}\0${x.bytes}\0${x.sha256}`).join("\n"))); write(MANIFEST, manifest);
  process.stdout.write(`${JSON.stringify({ status: "PASS", offline: true, runId: raw.runId, duplicateAndConservation: raw.duplicateAndConservation, aggregateSha256: manifest.aggregateSha256 })}\n`);
}

